/**
 * RPC stubs of the server's `turnstile` actions (server/src/actions/turnstile.rs):
 * the admin panel's Cloudflare Turnstile card. Not upstream, so not generated by
 * scripts/gen-actions.mjs (which writes src/rpc/actions/ from upstream's
 * app/actions/); written the same way.
 */
import { callAction } from "../runtime/rpc";

export type TurnstileSource = "panel" | "env" | "none";
export type TurnstileSecretState = "unset" | "set" | "undecryptable";

/** What the panel may know. Never the secret key. */
export interface TurnstileStatus {
  source: TurnstileSource;
  /** The switch as stored (from the environment: both keys set). */
  enabled: boolean;
  /** The check runs on the four forms. */
  active: boolean;
  /** Public: every protected page carries it. */
  siteKey: string;
  secretState: TurnstileSecretState;
  /** TURNSTILE_SITE_KEY and TURNSTILE_SECRET_KEY are both set. */
  envAvailable: boolean;
}

export type SaveTurnstileReason =
  | "invalid-site-key"
  | "invalid-secret"
  | "site-key-required"
  | "secret-required"
  | "secret-rejected"
  | "unreachable"
  | "rate-limited";

export type SaveTurnstileResult =
  | { ok: true; status: TurnstileStatus; changed: string[] }
  | { ok: false; reason: SaveTurnstileReason };

export type TurnstileTestResult =
  | { ok: true; alwaysPasses: boolean; tookMs: number }
  | { ok: false; kind: "no-secret" | "invalid-secret" | "rejected" | "unreachable" | "rate-limited"; tookMs: number };

export async function loadTurnstileStatus(): Promise<TurnstileStatus> {
  return callAction("turnstile", "loadTurnstileStatus", arguments);
}

/**
 * Save the card. A blank `secret` keeps the stored one while the site key stays
 * the same. Turning the check on first asks Cloudflare whether it accepts the
 * secret (a wrong one would keep everybody out, the administrator included).
 */
export async function saveTurnstileSettings(input: {
  enabled: boolean;
  siteKey: string;
  secret?: string;
}): Promise<SaveTurnstileResult> {
  return callAction("turnstile", "saveTurnstileSettings", arguments);
}

/** Forget the panel's block: TURNSTILE_* decides again. */
export async function clearTurnstileSettings(): Promise<TurnstileStatus> {
  return callAction("turnstile", "clearTurnstileSettings", arguments);
}

/** Does Cloudflare accept this secret (else the one in use)? Nothing is saved. */
export async function testTurnstileSecret(secret?: string): Promise<TurnstileTestResult> {
  return callAction("turnstile", "testTurnstileSecret", arguments);
}
